import { TUnPost } from '@/data/posts'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useEffect, useState } from 'react'
import {
  getLastFetchTime,
  getLsKey,
  setLastFetchTime,
  transformResponse,
} from './utils'

const api = import.meta.env.VITE_API_NEWS

const LS_PREFIX = 'lp_cached_'
const STALE_THRESHOLD_MS = 10 * 60 * 1000 // 10 minutes

export const useGetLastPost = (
  lang: 'fr' | 'ar',
  page?: string,
  rand?: boolean,
  bgRefresh?: boolean,
) => {
  const queryClient = useQueryClient()
  const [isBackgroundRefreshing, setIsBackgroundRefreshing] = useState(false)
  const queryKey = ['last', lang, page, !!rand]
  const query = useQuery({
    enabled: !!lang,
    staleTime: rand ? 1000 * 60 : STALE_THRESHOLD_MS,
    queryKey,
    queryFn: async () => {
      const response = await fetch(`${api}/lastnews?lang=${lang}&p=${page}`)
      if (!response.ok) {
        throw new Error('failed to fetch posts')
      }

      const { results: unformatedPosts, total }: categorieResponse =
        await response.json()

      const posts = transformResponse(unformatedPosts, rand)
      return { posts, total }
    },
  })

  // Background refresh for returning users (opt-in via bgRefresh param):
  // SW StaleWhileRevalidate serves stale cache instantly on return visits.
  // Once query settles, check if 10+ min passed since last fetch. If so,
  // fire a cache-busted fetch for fresh data and swap it in via setQueryData.
  // localStorage timestamp prevents duplicate fetches across re-renders.
  useEffect(() => {
    if (!bgRefresh || !query.isSuccess || query.isFetching) return

    const lsKey = getLsKey(LS_PREFIX, lang, page, rand)
    const lastFetch = getLastFetchTime(lsKey)

    if (lastFetch === null) {
      setLastFetchTime(lsKey)
      return
    }
    if (Date.now() - lastFetch < STALE_THRESHOLD_MS) return

    // Stamp immediately to prevent duplicate fetches across re-renders
    setLastFetchTime(lsKey)

    const controller = new AbortController()
    setIsBackgroundRefreshing(true)

    fetch(`${api}/lastnews?lang=${lang}&p=${page}&_cb=${Date.now()}`, {
      signal: controller.signal,
    })
      .then((res) => {
        if (!res.ok) throw new Error('bg refresh failed')
        return res.json()
      })
      .then(({ results: unformatedPosts, total }: categorieResponse) => {
        const posts = transformResponse(unformatedPosts, rand)
        if (posts.length > 0) {
          queryClient.setQueryData(queryKey, {
            posts,
            total,
          })
        }
      })
      .catch((err) => {
        if (err.name !== 'AbortError') {
          console.error('Background refresh failed', err)
        }
      })
      .finally(() => setIsBackgroundRefreshing(false))

    return () => controller.abort()
  }, [
    bgRefresh,
    query.isSuccess,
    query.isFetching,
    lang,
    page,
    rand,
    queryClient,
  ])

  return { ...query, isBackgroundRefreshing }
}

export interface categorieResponse {
  page: number
  pageSize: number
  total: number
  results: TUnPost[]
}
